import { useIntl } from 'react-intl';

import {
  DataStateHandler,
  ResponsiveBasicContainer,
  Skeleton,
} from 'components';
import { BigNumber } from 'components/BigNumber';
import { CustomTooltip } from 'components/CustomTooltip/CustomTooltip';
import { Icon, Info } from 'components/icon';
import { useCurrentPage, usePageFilterApplied } from 'hooks';

import { TooltipContent } from '../../../../components';
import { useAudiencePlanningKpiQuarterTags } from '../../../../hooks';
import { CARD_BACKGROUND_COLOR } from '../../../Performance/components/Breakdown/constants';
import { EMPTY_INTERACTIVE_SELECTION } from '../../constants';
import {
  InteractiveAudienceType,
  InteractivePercentage,
  InteractiveSelection,
} from '../../types';
import {
  BRAND_AUDIENCE_CARD_HEIGHT,
  BRAND_AUDIENCE_CARD_WIDTH,
  StyledAudienceGrid,
  StyledBrandAudienceBody,
  StyledBrandAudienceCardShell,
  StyledCardHeaderInfoIcon,
  StyledCardHeaderTitle,
  StyledCardHeaderTitleRow,
} from './BrandAudience.styles';
import {
  AUDIENCE_TOOLTIP_KEYS,
  BRAND_VOLUME_UNAVAILABLE_MESSAGE,
  CORE_AUDIENCE_TITLE,
  HALO_AUDIENCE_TITLE,
} from './constants';
import { buildInteractiveAudienceCardData } from './utils';

interface BrandAudienceProps {
  dataTestId?: string;
  isLoading: boolean;
  error: Error | null;
  hasData: boolean;
  activeAudience: InteractiveAudienceType | null;
  selection: InteractiveSelection;
  percentage: InteractivePercentage | null;
  isFetching: boolean;
  fetchError: Error | null;
  hasResult: boolean;
  onSelectAudience: (audience: InteractiveAudienceType) => void;
}

const AUDIENCE_CARDS: {
  type: InteractiveAudienceType;
  title: string;
}[] = [
  { type: 'core', title: CORE_AUDIENCE_TITLE },
  { type: 'halo', title: HALO_AUDIENCE_TITLE },
];

export const BrandAudience = ({
  dataTestId,
  isLoading,
  error,
  hasData,
  activeAudience,
  selection,
  percentage,
  isFetching,
  fetchError,
  hasResult,
  onSelectAudience,
}: BrandAudienceProps) => {
  const { formatMessage } = useIntl();
  const { currentPage } = useCurrentPage();
  const { applied } = usePageFilterApplied(currentPage);

  const fetchErrorMessage = formatMessage({
    id: 'Consumer.AudiencePlanning.Definition.BrandAudience.interactive.error.message',
  });

  const shouldRenderNoData = !isLoading && (!!error || !hasData);
  const kpiQuarterTags = useAudiencePlanningKpiQuarterTags();

  const renderNoDataState = () => {
    const messageKind = error ? 'error' : 'empty';

    return (
      <DataStateHandler
        loading={false}
        error={error ?? undefined}
        empty={!error}
        message={{
          title: formatMessage({
            id: `Consumer.AudiencePlanning.Definition.BrandAudience.${messageKind}Message.title`,
          }),
          description: formatMessage({
            id: `Consumer.AudiencePlanning.Definition.BrandAudience.${messageKind}Message.description`,
          }),
        }}
        dataTestId={dataTestId ? `${dataTestId}-state` : undefined}
      >
        {null}
      </DataStateHandler>
    );
  };

  const renderBody = () => {
    if (isLoading) {
      return (
        <StyledBrandAudienceBody>
          <Skeleton
            height={BRAND_AUDIENCE_CARD_HEIGHT}
            width={BRAND_AUDIENCE_CARD_WIDTH}
            length={2}
            dataTestId={dataTestId ? `skeleton-${dataTestId}` : undefined}
          />
        </StyledBrandAudienceBody>
      );
    }

    if (shouldRenderNoData) {
      return renderNoDataState();
    }

    return (
      <StyledBrandAudienceBody>
        <StyledAudienceGrid>
          {AUDIENCE_CARDS.map(({ type, title }, index) => {
            const isActive = activeAudience === type;
            const cardTestId = dataTestId
              ? `${dataTestId}-card-${index}`
              : undefined;
            const showError = isActive && !isFetching && !!fetchError;
            const showEmptyResult =
              isActive && !isFetching && !showError && hasResult;

            let selectionForCard: InteractiveSelection;
            if (isActive) {
              selectionForCard = selection;
            } else {
              selectionForCard = EMPTY_INTERACTIVE_SELECTION;
            }

            const percentageForCard = isActive ? percentage : null;

            let emptyMessage: string | undefined;
            if (showError) {
              emptyMessage = fetchErrorMessage;
            } else if (showEmptyResult) {
              emptyMessage = BRAND_VOLUME_UNAVAILABLE_MESSAGE;
            }

            const cardData = buildInteractiveAudienceCardData(
              type,
              selectionForCard,
              {
                isLoading: isActive && isFetching,
                percentage: percentageForCard,
                emptyMessage,
              },
            );

            return (
              <StyledBrandAudienceCardShell key={title}>
                <BigNumber
                  header={
                    <StyledCardHeaderTitleRow>
                      <StyledCardHeaderTitle>{title}</StyledCardHeaderTitle>
                      {AUDIENCE_TOOLTIP_KEYS[title] && (
                        <CustomTooltip
                          title={formatMessage({
                            id: AUDIENCE_TOOLTIP_KEYS[title].title,
                          })}
                          subtitle={formatMessage({
                            id: AUDIENCE_TOOLTIP_KEYS[title].subtitle,
                          })}
                          text={formatMessage({
                            id: AUDIENCE_TOOLTIP_KEYS[title].text,
                          })}
                        >
                          <StyledCardHeaderInfoIcon>
                            <Icon icon={Info} size="small" />
                          </StyledCardHeaderInfoIcon>
                        </CustomTooltip>
                      )}
                    </StyledCardHeaderTitleRow>
                  }
                  data={cardData}
                  size="small"
                  asCard
                  isSelected={isActive}
                  spacing="loose"
                  onClick={() => onSelectAudience(type)}
                  dataTestId={cardTestId}
                />
              </StyledBrandAudienceCardShell>
            );
          })}
        </StyledAudienceGrid>
      </StyledBrandAudienceBody>
    );
  };

  return (
    <ResponsiveBasicContainer
      dataTestId={dataTestId}
      header={{
        title: `${applied?.audience_targeting_brands ?? ''} ${formatMessage({
          id: 'Consumer.AudiencePlanning.Definition.BrandAudience.title',
        })}`,
        tags: kpiQuarterTags,
        titleSize: 'H2',
        tooltip: (
          <TooltipContent
            title={formatMessage({
              id: 'Consumer.AudiencePlanning.Definition.BrandAudience.tooltip.title',
            })}
            text={formatMessage({
              id: 'Consumer.AudiencePlanning.Definition.BrandAudience.tooltip.description',
            })}
            paddingLeft={false}
          />
        ),
        tooltipSize: 'medium',
      }}
      layout={{
        border: 'small',
        headerPadding: 'large',
        bodyPadding: true,
        background: CARD_BACKGROUND_COLOR,
      }}
    >
      {renderBody()}
    </ResponsiveBasicContainer>
  );
};
